local function codepoint(mapping, first, second)
  local cell = (first - 0xa1) * 94 + (second - 0xa1)
  local offset = cell * 2 + 1
  local high, low = mapping:byte(offset, offset + 1)
  local value = high * 0x100 + low
  return value ~= 0 and value or nil
end

local function utf8_char(value)
  if value <= 0x7f then
    return string.char(value)
  elseif value <= 0x7ff then
    return string.char(0xc0 + math.floor(value / 0x40), 0x80 + value % 0x40)
  end
  return string.char(
    0xe0 + math.floor(value / 0x1000),
    0x80 + math.floor(value / 0x40) % 0x40,
    0x80 + value % 0x40
  )
end

local function invalid(position, message)
  error(("EUC-JP byte %d: %s"):format(position, message), 0)
end

function M.decode(content)
  local chunks = {}
  local pending = {}
  local position = 1

  local function append(value)
    pending[#pending + 1] = value
    if #pending == 4096 then
      chunks[#chunks + 1] = table.concat(pending)
      pending = {}
    end
  end

  while position <= #content do
    local first = content:byte(position)
    if first <= 0x7f then
      append(string.char(first))
      position = position + 1
    elseif first == 0x8e then
      local second = content:byte(position + 1)
      if not second or second < 0xa1 or second > 0xdf then
        invalid(position, "invalid half-width katakana sequence")
      end
      append(utf8_char(0xff61 + second - 0xa1))
      position = position + 2
    elseif first == 0x8f then
      local second, third = content:byte(position + 1, position + 2)
      if not second or not third or second < 0xa1 or second > 0xfe or third < 0xa1 or third > 0xfe then
        invalid(position, "invalid JIS X 0212 sequence")
      end
      local value = codepoint(jis0212, second, third)
      if not value then
        invalid(position, "unassigned JIS X 0212 cell")
      end
      append(utf8_char(value))
      position = position + 3
    elseif first >= 0xa1 and first <= 0xfe then
      local second = content:byte(position + 1)
      if not second or second < 0xa1 or second > 0xfe then
        invalid(position, "invalid JIS X 0208 sequence")
      end
      local value = codepoint(jis0208, first, second)
      if not value then
        invalid(position, "unassigned JIS X 0208 cell")
      end
      append(utf8_char(value))
      position = position + 2
    else
      invalid(position, ("invalid lead byte 0x%02x"):format(first))
    end
  end

  chunks[#chunks + 1] = table.concat(pending)
  return table.concat(chunks)
end

return M
